{"path": "units/chain/stage1.py", "content": """"Stage 1: read the orders CSV into a list of int-valued dicts."""

import csv


def parse_orders(path):
    """Read the CSV at *path* (header ``id,qty,price``).

    Returns a list of ``{"id": int, "qty": int, "price": int}`` dicts, one per
    data row, in file order.
    """
    rows = []
    with open(path, newline="", encoding="utf-8") as fh:
        reader = csv.DictReader(fh)
        for record in reader:
            rows.append(
                {
                    "id": int(record["id"]),
                    "qty": int(record["qty"]),
                    "price": int(record["price"]),
                }
            )
    return rows
"}

{"path": "units/chain/stage3.py", "content": """"Stage 3: aggregate quantities by price."""


def total_by_price(rows):
    """Return ``{price: sum(qty)}`` over *rows*."""
    totals = {}
    for row in rows:
        price = row["price"]
        totals[price] = totals.get(price, 0) + row["qty"]
    return totals
"}

{"path": "units/chain/stage4.py", "content": """"Stage 4: render the aggregated totals as a report string."""


def report(totals):
    """Format *totals* as one ``"price:total"`` line per price.

    Lines are sorted by price ascending and each line is terminated by ``"\\n"``.
    """
    lines = ["%d:%d" % (price, totals[price]) for price in sorted(totals)]
    return "".join(line + "\n" for line in lines)
